15. 최소 1개 이상의 노드로 이루어진 원형 연결 리스트(circular linked
list)에서 포인터 L이 리스트의 첫 번째 노드를 가리킨다고 할 때,
데이터의 값이 x인 노드를 탐색하여 반환하는 C 코드는?
①ListNode *searchCList(ListNode *L, int x) {
ListNode *p=L;
while(p!=L) {
if(p->data==x) return p;
p=p->link;
}
return NULL;
}
②ListNode *searchCList(ListNode *L, int x) {
ListNode *p=L;
while(p->link!=L) {
if(p->data==x) return p;
p=p->link;
}
return NULL;
}
③ListNode *searchCList(ListNode *L, int x) {
ListNode *p=L;
do {
if(p->data==x) return p;
p=p->link;
} while(p!=L);
return NULL;
}
④ListNode *searchCList(ListNode *L, int x) {
ListNode *p=L;
do {
if(p->data==x) return p;
p=p->link;
} while(p->link!=L);
return NULL;
}

